package io.github.devicebridge.android;
import android.content.Context;import android.net.Uri;import java.io.*;import java.security.*;import java.util.*;
/** App-private immutable bytes for review and later device transfer. Never follows a file URI as a stream. */
final class LocalSnapshot {
 final File file;final long bytes;final String sha256;
 private LocalSnapshot(File file)throws IOException{this.file=file;bytes=file.length();try{MessageDigest hash=MessageDigest.getInstance("SHA-256");try(InputStream input=new FileInputStream(file)){byte[] block=new byte[65536];int n;while((n=input.read(block))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("快照已取消");hash.update(block,0,n);}}StringBuilder out=new StringBuilder();for(byte value:hash.digest())out.append(String.format(Locale.ROOT,"%02x",value&255));sha256=out.toString();}catch(NoSuchAlgorithmException impossible){throw new IOException(impossible);}}
 static LocalSnapshot create(Context context,Uri source,String expectedToken)throws IOException{File directory=new File(context.getCacheDir(),"gb-snapshot-"+UUID.randomUUID());if(!directory.mkdir())throw new IOException("无法创建私有快照目录");File destination=new File(directory,"content");boolean good=false;try{if("file".equals(source.getScheme()))Compatibility.copyVerifiedSource(new File(source.getPath()),destination,expectedToken);else try(InputStream input=context.getContentResolver().openInputStream(source);OutputStream output=Compatibility.createExclusive(destination)){if(input==null)throw new IOException("无法读取所选文件");byte[] block=new byte[65536];int n;while((n=input.read(block))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("快照已取消");output.write(block,0,n);}}LocalSnapshot snapshot=new LocalSnapshot(destination);if(!destination.setReadOnly())throw new IOException("无法固定私有快照权限");good=true;return snapshot;}finally{if(!good){destination.delete();directory.delete();}}}
 static void verify(File file,String expectedHash)throws IOException{if(!new LocalSnapshot(file).sha256.equals(expectedHash))throw new IOException("已确认的私有快照内容改变，请重新选择文件");}
 static void dispose(File file){if(file==null)return;File directory=file.getParentFile();file.delete();if(directory!=null&&directory.getName().startsWith("gb-snapshot-"))directory.delete();}
}
